import React, { useEffect, useState, useCallback } from 'react';
import { visitsAPI, visitorsAPI, hostsAPI } from '../services/api';
import { useAuth } from '../context/AuthContext';
import { useNavigate, useLocation } from 'react-router-dom';

const STATUS_OPTIONS = ['pending','approved','refused','ongoing','completed','cancelled'];
const STATUS_LABELS  = {
  pending:   'En attente',
  approved:  'Approuvée',
  refused:   'Refusée',
  ongoing:   'En cours',
  completed: 'Terminée',
  cancelled: 'Annulée',
};

function Toast({ msg, type, onDone }) {
  useEffect(() => { const t = setTimeout(onDone, 2500); return () => clearTimeout(t); }, [onDone]);
  return <div className={`toast ${type}`}>{msg}</div>;
}

export default function Visits() {
  const { user } = useAuth();
  const navigate = useNavigate();
  const location = useLocation();

  const [visits, setVisits] = useState([]);
  const [visitors, setVisitors] = useState([]);
  const [hosts, setHosts] = useState([]);
  const [loading, setLoading] = useState(true);
  const [showModal, setShowModal] = useState(false);
  const [editVisit, setEditVisit] = useState(null);
  const [toast, setToast] = useState(null);

  const [filterStatus, setFilterStatus] = useState('');
  const [filterHost, setFilterHost] = useState('');
  const [filterDate, setFilterDate] = useState('');

  const [form, setForm] = useState({
    visitor_id: '', host_id: '', purpose: '', scheduled_at: '', notes: ''
  });

  const isNew = location.pathname === '/visits/new';
  const isVisitor = user?.role === 'visitor';
  const isAdmin = user?.role === 'admin';
  const isAgent = user?.role === 'agent';
  const isHost = user?.role === 'host';

  const load = useCallback(async () => {
    setLoading(true);
    try {
      const filters = {};
      if (filterStatus) filters.status = filterStatus;
      if (filterHost) filters.host_id = filterHost;
      if (filterDate) filters.date = filterDate;
      const res = await visitsAPI.getAll(filters);
      setVisits(res.data);
    } finally { setLoading(false); }
  }, [filterStatus, filterHost, filterDate]);

  useEffect(() => { load(); }, [load]);

  useEffect(() => {
    hostsAPI.getAll().then(h => setHosts(h.data));
    if (isAdmin || isAgent) {
      visitorsAPI.getAll().then(v => setVisitors(v.data));
    }
  }, [isAdmin, isAgent]);

  const openCreate = () => {
    setEditVisit(null);
    setForm({
      visitor_id: isVisitor ? user.id : '',
      host_id: '',
      purpose: '',
      scheduled_at: '',
      notes: ''
    });
    setShowModal(true);
  };

  const handleSave = async () => {
    if (!form.host_id || !form.scheduled_at) {
      setToast({ msg: 'Champs obligatoires', type: 'error' });
      return;
    }

    try {
      if (editVisit) {
        await visitsAPI.update(editVisit.id, form);
      } else {
        await visitsAPI.create(form);
      }
      setShowModal(false);
      load();
    } catch {
      setToast({ msg: 'Erreur', type: 'error' });
    }
  };

  const canEdit = isAdmin || isAgent;
  const canStatus = isAdmin || isAgent || isHost;

  return (
    <div className="page">

      {/* HEADER */}
      <div className="page-header">
        <div>
          <h1 className="page-title">Visites</h1>
          <p className="page-sub">{visits.length} visites</p>
        </div>

        {/* 🔒 CORRECTION ICI */}
        {(isAdmin || isAgent || isVisitor) && (
          <button className="btn btn-primary" onClick={openCreate}>
            + {isVisitor ? 'Demander une visite' : 'Nouvelle visite'}
          </button>
        )}
      </div>

      {/* TABLE */}
      <div className="card">
        {loading ? (
          <p>Chargement...</p>
        ) : (
          <table>
            <thead>
              <tr>
                <th>#</th>
                <th>Visiteur</th>
                <th>Hôte</th>
                <th>Objet</th>
                <th>Date</th>
                <th>Statut</th>
                <th>Actions</th>
              </tr>
            </thead>
            <tbody>
              {visits.map(v => (
                <tr key={v.id}>
                  <td>{v.id}</td>
                  <td>{v.visitor_name}</td>
                  <td>{v.host_name}</td>
                  <td>{v.purpose}</td>
                  <td>{new Date(v.scheduled_at).toLocaleString()}</td>
                  <td>{STATUS_LABELS[v.status]}</td>
                  <td>
                    {canEdit && <button>Modifier</button>}
                    {canStatus && v.status === 'pending' && (
                      <>
                        <button onClick={() => visitsAPI.updateStatus(v.id, 'approved')}>OK</button>
                        <button onClick={() => visitsAPI.updateStatus(v.id, 'refused')}>Refus</button>
                      </>
                    )}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </div>

      {/* MODAL */}
      {showModal && (
        <div className="modal">
          <h3>Nouvelle visite</h3>

          <select value={form.host_id} onChange={e => setForm(f => ({ ...f, host_id: e.target.value }))}>
            <option>Choisir un hôte</option>
            {hosts.map(h => <option key={h.id} value={h.id}>{h.name}</option>)}
          </select>

          <input type="datetime-local"
            value={form.scheduled_at}
            onChange={e => setForm(f => ({ ...f, scheduled_at: e.target.value }))}
          />

          <button onClick={handleSave}>Créer</button>
        </div>
      )}

      {toast && <Toast {...toast} onDone={() => setToast(null)} />}
    </div>
  );
}
